              if grid[r][c] != background]
    out = [row[:] for row in grid]

    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            steps = gcd(abs(dr), abs(dc))
            if steps > 1:
                sr, sc = dr // steps, dc // steps
                for k in range(1, steps):
